import test from 'node:test';
import assert from 'node:assert/strict';
import {SEGMENTS,points,visit,routes,rankedRoutes,setup,emptyMemory,validMemory,addObservation,setFact,currentFacts,removeFact,assessments,investigate,plan,wilson,ALLOCATION_PROOF} from '../site/engine/engine.mjs';
import {technicalInvestigation,evaluation,executive} from '../site/engine/reasoning.mjs';
import {knowledge} from '../site/engine/knowledge.mjs';
function day(i){return new Date(Date.UTC(2024,0,1+i)).toISOString().slice(0,10)}
function obs(i,skill='doubles',hits=20,context='practice',protocol='fixed',attempts=60){return {id:[i,skill,context,protocol].join('/'),day:day(i),skill,hits,attempts,context,protocol}}
function series(skill='doubles',a=30,b=12){let m=emptyMemory();for(let i=0;i<14;i++)m=addObservation(m,obs(i,skill,i<7?a:b));return m}
test('independent exhaustive checkout oracle, 1/2/3 darts',()=>{const scores=[...Array.from({length:20},(_,i)=>i+1),...Array.from({length:20},(_,i)=>2*(i+1)),...Array.from({length:20},(_,i)=>3*(i+1)),25,50];let possible=new Set(Array.from({length:20},(_,i)=>2*(i+1)).concat(50));for(let d=1;d<=3;d++){for(let n=2;n<=180;n++){const rs=routes(n,d);assert.equal(rs.length>0,possible.has(n));for(const p of rs){assert.ok(p.length<=d);assert.equal(p.reduce((a,s)=>a+points(s),0),n);assert.equal(visit(n,p).finished,true)}}possible=new Set([...possible,...[...possible].flatMap(x=>scores.map(y=>x+y))])}});
test('bust, double-in, miss and recovery',()=>{assert.equal(visit(40,['S20','S20']).remaining,40);assert.equal(visit(40,['S20','D10']).finished,true);assert.equal(visit(50,['50']).finished,true);assert.equal(visit(101,['T20','D20'],{doubleIn:true}).remaining,61);assert.equal(visit(101,['D20','T20'],{doubleIn:true}).opened,false);assert.equal(visit(40,['MISS','D20']).used,2);assert.throws(()=>visit(40,['D20','garbage']));assert.throws(()=>routes(1));assert.throws(()=>points('D25'))});
test('all displayed rankings remain legal',()=>{for(const s of [2,32,40,50,81,99,110,170])for(const x of rankedRoutes(s,3)){assert.equal(visit(s,x.path).finished,true);assert.equal(x.estimate,null)}});
test('setup avoids leaving 1 or bust',()=>{for(const s of [2,41,62,99,170,181,501])for(const x of setup(s)){assert.equal(s-points(x.target),x.remaining);assert.ok(x.remaining>=2)}});
test('memory validation, correction, deletion, foreign backups',()=>{let m=setFact(emptyMemory(),'grip','front');m=setFact(m,'grip','middle','confirmed');assert.equal(currentFacts(m)[0].value,'middle');assert.equal(m.facts.length,2);assert.equal(removeFact(m,'grip').facts.length,0);assert.throws(()=>validMemory({...m,namespace:'DCAI'}));m=addObservation(m,obs(0));assert.throws(()=>addObservation(m,obs(0)));assert.throws(()=>addObservation(m,obs(1,'doubles',61)));assert.throws(()=>addObservation(m,{...obs(1),day:'2024-02-31'}));assert.deepEqual(validMemory(JSON.parse(JSON.stringify(m))),m)});
test('independent skill/context/protocol assessments and no premature action',()=>{let m=series();assert.equal(investigate(m).focus,'doubles');m=addObservation(m,obs(0,'doubles',50,'competition'));assert.equal(assessments(m).length,2);assert.equal(investigate(emptyMemory()).decision,'balanced');assert.equal(investigate({...m,observations:m.observations.slice(0,3)}).decision,'balanced');assert.equal(investigate(series('scoring',1200,1400)).decision,'balanced')});
test('contradictory evidence and prior unsuccessful intervention prevent repeated focus',()=>{let m=series();for(let i=0;i<14;i++)m=addObservation(m,obs(i,'doubles',i<7?10:30,'competition','match'));assert.equal(investigate(m).decision,'investigate');m=series();m.interventions.push({id:'i',skill:'doubles',context:'practice',protocol:'fixed',action:'focus',status:'unsuccessful'});assert.equal(investigate(m).decision,'temporary-focus');m.interventions[0][ALLOCATION_PROOF]=true;assert.equal(investigate(m).decision,'investigate')});
test('same-day repetitions cannot masquerade as independent days',()=>{let m=emptyMemory();for(let i=0;i<100;i++)m=addObservation(m,{...obs(0),id:String(i)});assert.equal(assessments(m)[0].trend.status,'insufficient')});
test('training budget and variety invariants',()=>{for(const skill of [null,'doubles','scoring','checkout','bull','singles','switching','setup','pressure']){const p=plan(skill);assert.equal(p.reduce((n,x)=>n+x.minutes,0),60);assert.equal(p[0].minutes,10);assert.ok(p.every(x=>x.minutes>=5));assert.equal(new Set(p.map(x=>x.skill)).size,p.length)}});
test('technical safety and no fabricated causal diagnosis',()=>{const x=technicalInvestigation({skill:'doubles',symptom:'left misses'});assert.equal(x.decision,'collect-evidence');assert.ok(x.hypotheses.every(h=>h.status==='unresolved'));assert.equal(technicalInvestigation({skill:'doubles',pain:true}).decision,'stop')});
test('intervention evaluation refuses incompatible or unadhered evidence',()=>{const m=series(),a=assessments({...m,observations:m.observations.slice(0,7)})[0],b=assessments({...m,observations:m.observations.slice(7)})[0];assert.equal(evaluation(a,b).status,'confounded');assert.equal(evaluation(a,b,{adherence:1}).status,'observed-decline');assert.equal(evaluation(a,{...b,context:'competition'},{adherence:1}).status,'not-comparable')});
test('knowledge ids and relations resolve; no unlabelled source',()=>{const ids=new Set(knowledge.map(k=>k.id));assert.equal(ids.size,knowledge.length);for(const k of knowledge){assert.ok(k.source&&k.level&&k.limitations);assert.ok(k.related.every(id=>ids.has(id)))}});
test('Wilson interval edge cases',()=>{assert.ok(wilson(0,60)[1]<.1);assert.ok(wilson(60,60)[0]>.9);assert.throws(()=>wilson(1,0))});
test('seeded 1000 synthetic players, 52 weeks, balanced and declining trajectories',()=>{let seed=0xDC110;const rng=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);for(let j=0;j<1000;j++){const m=emptyMemory(),declining=j%2===0,base=25+Math.floor(rng()*10);for(let w=0;w<52;w++){const h=base+Math.floor(rng()*3)-1-(declining&&w>=45?15:0);m.observations.push(obs(w*7,'doubles',h));}const r=executive(m);assert.equal(r.decision,declining?'temporary-focus':'balanced');assert.equal(r.plan.reduce((n,x)=>n+x.minutes,0),60)}});

import {classify,appendThrow,targetSummaries,modelFor,missAwarePolicy} from '../site/engine/target-evidence.mjs';
import {validateState} from '../site/engine/state.mjs';
test('board adjacency, ring separation and ambiguous singles',()=>{assert.equal(classify('D20','S1'),'clockwise-neighbour');assert.equal(classify('D20','S5'),'anticlockwise-neighbour');assert.equal(classify('L20','I20'),'same-number-different-ring');assert.equal(classify('S20','I20'),'exact');assert.equal(classify('T20','MISS'),'off-board');assert.throws(()=>classify('MISS','D20'))});
test('target observations and same-context miss-aware recovery',()=>{let m=emptyMemory();for(let i=0;i<70;i++){m=appendThrow(m,{id:'t'+i,day:day(Math.floor(i/10)),context:'practice',protocol:'same',aim:'D20',actual:i%2?'D20':'S20'});m=appendThrow(m,{id:'d'+i,day:day(Math.floor(i/10)),context:'practice',protocol:'same',aim:'D10',actual:i%2?'D10':'MISS'})}assert.equal(validateState(m).throws.length,140);assert.equal(targetSummaries(m.throws).find(g=>g.aim==='D20').hits,35);const model=modelFor(m.throws,'practice','same');assert.equal(missAwarePolicy(40,1,model).options[0].estimate,.5);assert.equal(missAwarePolicy(40,2,model).options[0].estimate,.75);assert.equal(missAwarePolicy(40,2,modelFor(m.throws,'competition','same')).status,'insufficient');assert.throws(()=>validateState({...m,throws:[m.throws[0],m.throws[0]]}));assert.equal(validateState(emptyMemory()).throws.length,0)});

import {propose,respond,review,finish,currentPlan} from '../site/engine/interventions.mjs';
test('consent, bounded focus, matched intervention review and expiry',()=>{let m=series();const report=executive(m);assert.equal(currentPlan(m,report,day(14)).mode,'balanced-until-accepted');m=propose(m,report,'trial',day(14));assert.throws(()=>propose(m,report,'second',day(14)));assert.equal(validateState(m).interventions.length,1);m=respond(m,'trial','accepted',day(14));assert.equal(currentPlan(m,report,day(15)).mode,'accepted-temporary-focus');assert.equal(currentPlan(m,report,day(28)).mode,'review-due');assert.equal(currentPlan(m,report,day(35)).mode,'review-required');assert.equal(review(m,'trial',day(20),{adherence:1}).status,'too-early');assert.equal(review(m,'trial',day(28),{adherence:1}).status,'insufficient');for(let i=15;i<=28;i++)m=addObservation(m,obs(i,'doubles',30));assert.equal(review(m,'trial',day(28),{adherence:1}).status,'observed-improvement');assert.equal(review(m,'trial',day(28),{adherence:.5}).status,'confounded');assert.equal(review(m,'trial',day(28),{adherence:1,confounders:['new darts']}).status,'confounded');const result=finish(m,'trial',day(28),{adherence:1});assert.equal(result.interventions[0].status,'completed');assert.equal(result.interventions[0].outcome.causality,'not established');assert.equal(currentPlan(result,executive(result),day(29)).mode,'balanced-until-accepted');assert.equal(validateState(result).interventions[0].status,'completed');assert.equal(review({...m,observations:m.observations.filter(o=>o.id!==m.interventions[0].baselineIds[0])},'trial',day(28),{adherence:1}).status,'baseline-edited')});

import {recordReadiness,matchedContext,robustTrend,exposureSummary} from '../site/engine/context.mjs';
import {recordDifficulty,difficultyDecision,variant,library} from '../site/engine/training.mjs';
import {equipmentInvestigation,mentalSupport,evidenceReview,drillPlan,selectCoaching,learningHistory} from '../site/engine/player-intelligence.mjs';
test('calendar windows exclude stale observations and isolated spike',()=>{const m=emptyMemory();for(let i=0;i<56;i++)m.observations.push(obs(i,'doubles',i<28?30:12));assert.equal(robustTrend(m.observations,{asOf:day(55)}).status,'declining');assert.equal(robustTrend(m.observations,{asOf:day(120)}).status,'insufficient');const flat=m.observations.map(o=>({...o,hits:30}));flat.at(-1).hits=0;assert.equal(robustTrend(flat,{asOf:day(55)}).status,'unclear');assert.equal(robustTrend([...flat,obs(0,'scoring',500)],{asOf:day(55)}).status,'not-comparable')});
test('readiness corrections, isolation and associations are not causal',()=>{let m=emptyMemory();for(let i=0;i<14;i++){m=addObservation(m,obs(i,'doubles',i<7?30:12));m=recordReadiness(m,{day:day(i),context:'practice',fatigue:i<7?'normal':'high',pressure:'normal',confidence:'normal',pain:false,note:''})}const a=matchedContext(m.observations,m.readiness,'fatigue');assert.equal(a.status,'association');assert.equal(a.causality,'not established');assert.ok(a.change<0);assert.equal(selectCoaching(m,executive(m),day(13)).decision,'reduce-load');assert.equal(selectCoaching(m,executive(m),day(14)).decision,'investigate');m=recordReadiness(m,{...m.readiness.at(-1),fatigue:'normal'});assert.equal(m.readiness.length,14);assert.equal(validateState(m).readiness.length,14);assert.throws(()=>validateState({...m,readiness:[m.readiness[0],m.readiness[0]]}));assert.equal(matchedContext(m.observations,[],'pressure').status,'insufficient')});
test('all independent skills: challenge progression, reduction, no change on tiny samples',()=>{for(const skill of library.map(x=>x.skill)){let m=emptyMemory();for(let i=0;i<7;i++)m=recordDifficulty(m,{id:skill+i,day:day(i),skill,protocol:skill+'-core',level:3,attempts:10,successes:9});assert.equal(difficultyDecision(m.difficulty,skill,skill+'-core',3,day(6)).next,4);assert.equal(difficultyDecision(m.difficulty,skill,skill+'-core',4,day(6)).next,4);assert.equal(difficultyDecision(m.difficulty.map(x=>({...x,successes:1})),skill,skill+'-core',3,day(6)).next,2);assert.equal(difficultyDecision(m.difficulty.slice(0,2),skill,skill+'-core',3,day(6)).next,3);assert.equal(variant(skill,1).instructions,variant(skill,2).instructions);assert.equal(difficultyDecision(m.difficulty.map(x=>({...x,level:7})),skill,skill+'-core',7,day(6)).next,7);assert.equal(difficultyDecision(m.difficulty.map(x=>({...x,level:1,successes:0})),skill,skill+'-core',1,day(6)).next,1);assert.equal(validateState(m).difficulty.length,7)}});
test('five-day rotation covers all eleven skills without dropping core or warm-up',()=>{const covered=new Set();for(let d=0;d<5;d++){const p=drillPlan(emptyMemory(),day(d));assert.equal(p.reduce((s,x)=>s+x.minutes,0),60);assert.equal(p[0].minutes,10);assert.ok(p.every(x=>x.minutes>=5));assert.ok(p.some(x=>x.skill==='doubles'));for(const x of p)covered.add(x.skill)}for(const skill of library.map(x=>x.skill))assert.ok(covered.has(skill))});
test('equipment changes are isolated, no purchases and pain veto across contexts',()=>{assert.equal(equipmentInvestigation().decision,'preserve');assert.equal(equipmentInvestigation({changed:['weight'],measuredDecline:true}).decision,'controlled-comparison');assert.equal(equipmentInvestigation({changed:['weight','stem length'],measuredDecline:true}).decision,'isolate');assert.equal(equipmentInvestigation({changed:['weight'],discomfort:true}).decision,'stop-and-review');assert.equal(mentalSupport([{day:day(0),pain:false},{day:day(0),pain:true}]).decision,'stop');assert.throws(()=>equipmentInvestigation({changed:['invented']}))});
test('priority is stable under reordered input, stale data cannot trigger intervention',()=>{let m=series();assert.equal(selectCoaching(m,executive(m),day(14)).focus,'doubles');assert.equal(selectCoaching(m,executive(m),day(100)).focus,null);for(let i=0;i<14;i++)m=addObservation(m,obs(i,'scoring',i<7?2000:1200));const a=selectCoaching(m,executive(m),day(14)),b=selectCoaching({...m,observations:[...m.observations].reverse()},executive({...m,observations:[...m.observations].reverse()}),day(14));assert.equal(a.focus,b.focus);assert.equal(a.focus,'scoring')});
test('two-year seeded calendar-window holdout population: decline, flat, improvement and noise',()=>{let seed=0x4bc617;const rng=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);for(let player=0;player<500;player++){const m=emptyMemory(),type=player%4,base=20+Math.floor(rng()*12);for(let week=0;week<104;week++)for(let session=0;session<3;session++){const i=week*7+session*2;const change=week>=100?(type===0?-12:type===2?12:0):0;const noise=Math.floor(rng()*5)-2;const hits=Math.max(0,Math.min(60,base+change+noise+(type===3&&week===103&&session===2?-10:0)));m.observations.push(obs(i,'doubles',hits))}const result=evidenceReview(m,day(727));const t=result.profiles[0].trend.status;assert.equal(t,type===0?'declining':type===2?'improving':'unclear');assert.equal(result.focus,type===0?'doubles':null);assert.equal(result.profiles[0].trend.blocks.length,2)}});

import {retentionReview,recordRetention,dailyDistribution} from '../site/engine/learning.mjs';
test('later retention is assessed separately, never assumed from initial improvement',()=>{let m=series();m=propose(m,executive(m),'trial',day(14));m=respond(m,'trial','accepted',day(14));for(let i=15;i<=28;i++)m=addObservation(m,obs(i,'doubles',30));m=finish(m,'trial',day(28),{adherence:1});assert.equal(retentionReview(m,'trial',day(35)).status,'too-early');assert.equal(retentionReview(m,'trial',day(42)).status,'insufficient');for(let i=29;i<=42;i++)m=addObservation(m,obs(i,'doubles',30));assert.equal(retentionReview(m,'trial',day(42)).status,'observed-retention');m=recordRetention(m,'trial',day(42));assert.equal(m.interventions[0].retentionHistory.length,1);assert.equal(recordRetention(m,'trial',day(42)).interventions[0].retentionHistory.length,1);assert.equal(retentionReview({...m,observations:m.observations.map(o=>o.day>day(28)?{...o,hits:12}:o)},'trial',day(42)).status,'retention-not-established');assert.equal(retentionReview({...m,interventions:[...m.interventions,{id:'other',skill:'doubles',status:'accepted',responseDay:day(30)}]},'trial',day(42)).status,'confounded')});
test('descriptive distributions have exact medians and do not claim inferential confidence',()=>{const d=dailyDistribution([obs(0,'doubles',0),obs(1,'doubles',30),obs(2,'doubles',60)]);assert.equal(d.median,.5);assert.equal(d.q1,.25);assert.equal(d.q3,.75);assert.equal(d.minimum,0);assert.equal(d.maximum,1);assert.equal(dailyDistribution([]),null)});
test('active intervention cannot override safety or context review',()=>{let m=series();m=propose(m,executive(m),'trial',day(14));m=respond(m,'trial','accepted',day(14));assert.equal(currentPlan(m,{decision:'stop'},day(15)).plan.length,0);assert.equal(currentPlan(m,{decision:'reduce-load'},day(15)).mode,'reduce-load');assert.equal(currentPlan(m,{decision:'investigate',review:{profiles:[{skill:'doubles',context:'practice',protocol:'fixed',hypotheses:[{id:'fatigue',status:'supported-as-possibility'}]}]}},day(15)).mode,'review-context')});

import {recordAnswer,recordChange,investigateIssue,deepenReport,matchedWithinWeeks,exposureComparison} from '../site/engine/diagnosis.mjs';
import {beginTrial,addPair,nextOrder,trialOutcome,finishTrial,approachHistory} from '../site/engine/experiments.mjs';
import {DRILLS,drillOptions,trainingRecommendation,logSession} from '../site/engine/session-intelligence.mjs';
import {explainReport,relevantPrinciples} from '../site/engine/explanation.mjs';
import {SCENARIOS,scenario} from '../site/engine/scenarios.mjs';
function deep(m,date){return deepenReport(m,selectCoaching(m,executive(m),date),date)}
test('all nine diagnostic scenarios have independent expected decisions',()=>{const expected={decline:'temporary-focus',stable:'balanced',fatigue:'investigate',equipment:'investigate',measurement:'investigate',sparse:'balanced',pressure:'investigate',pain:'stop',exposure:'temporary-focus'};for(const [id] of SCENARIOS){const s=scenario(id),before=JSON.stringify(s.memory),x=deep(s.memory,s.day);assert.equal(x.decision,expected[id],id);assert.equal(JSON.stringify(s.memory),before);assert.ok(explainReport(x,s.memory).reason.length>0)}});
test('explanation rounds percentage correctly and never asserts a cause',()=>{const s=scenario('decline'),x=deep(s.memory,s.day),e=explainReport(x,s.memory),i=e.issues[0];assert.equal(i.evidence.earlier,'50%');assert.equal(i.evidence.recent,'20%');assert.equal(i.evidence.difference,'-30 percentage points');assert.equal(i.evidence.samples[0],420);assert.ok(i.hypotheses.every(h=>h.statusLabel));assert.ok(i.principles.some(k=>k.id==='context'));assert.equal(i.allocation.status,'incomplete-logging')});
test('question responses revise decisions, keep history and isolate protocols',()=>{const s=scenario('decline');let m=s.memory;const o={day:s.day,skill:'doubles',context:'practice',protocol:'Fixed D1–D20',question:'equipment',answer:'yes'};m=recordAnswer(m,o);assert.equal(deep(m,s.day).decision,'investigate');m=recordAnswer(m,{...o,answer:'no'});assert.equal(deep(m,s.day).decision,'temporary-focus');assert.equal(m.answers.length,2);assert.equal(deep(recordAnswer(m,{...o,protocol:'other'}),s.day).decision,'temporary-focus');assert.throws(()=>recordAnswer(m,{...o,answer:'made-up'}));assert.equal(validateState(m).answers.length,2)});
test('individual practice allocation comparison requires complete logging and two windows',()=>{const s=scenario('exposure'),x=deep(s.memory,s.day),i=x.issues[0];assert.equal(i.investigation.exposure.status,'decreased');assert.equal(i.investigation.exposure.earlier.perWeek,140);assert.equal(i.investigation.exposure.recent.perWeek,35);assert.ok(i.investigation.hypotheses.find(h=>h.id==='practice').support.length);assert.equal(deep({...s.memory,answers:[]},s.day).issues[0].investigation.exposure.status,'incomplete-logging')});
test('within-week comparison rejects pure time confound and detects replicated association',()=>{const s=scenario('fatigue'),i={skill:'doubles',context:'practice',protocol:'Fixed D1–D20'};assert.equal(matchedWithinWeeks(s.memory,i,s.day,'fatigue','high').status,'insufficient');let m=emptyMemory();for(let j=0;j<28;j++){const high=j%2===0; m=addObservation(m,obs(j,'doubles',high?12:30,'practice','fixed'));m=recordReadiness(m,{day:day(j),context:'practice',fatigue:high?'high':'normal',pressure:'normal',confidence:'normal',pain:false,note:''})}const z=matchedWithinWeeks(m,{...i,protocol:'fixed'},day(27),'fatigue','high');assert.equal(z.status,'association');assert.ok(Math.abs(z.delta+.3)<1e-12);assert.equal(z.causality,'not established')});
test('reported change after the onset does not become a cause automatically',()=>{const s=scenario('decline');const m=recordChange(s.memory,{id:'late',day:'2026-01-14',field:'equipment',description:'new barrel'});assert.equal(deep(m,s.day).decision,'temporary-focus');assert.equal(validateState(m).changes.length,1)});
function trial(m=emptyMemory(),id='trial',alternative='external cue'){return beginTrial(m,{id,start:day(0),skill:'doubles',context:'practice',protocol:'fixed',approach:'attention cue',baseline:'normal cue',alternative,firstOrder:'AB'})}
function paired(m,d,a,b,extra={}){const t=m.trials.find(t=>t.status==='active');return addPair(m,t.id,{day:day(d),order:nextOrder(t),attempts:20,a,b,comparable:true,discomfort:false,...extra})}
test('paired experiments alternate order, enforce equal attempts and record personal outcomes',()=>{let m=trial();assert.equal(nextOrder(m.trials[0]),'AB');m=paired(m,0,6,12);assert.equal(nextOrder(m.trials[0]),'BA');assert.throws(()=>paired(m,0,6,12));assert.throws(()=>finishTrial(m,'trial'));for(let i=1;i<6;i++)m=paired(m,i,6,12);assert.equal(trialOutcome(m.trials[0]).status,'alternative-favoured');m=finishTrial(m,'trial');assert.equal(approachHistory(m,'doubles','fixed','practice','attention cue','normal cue','external cue').favoured,1);assert.equal(validateState(m).trials.length,1)});
test('paired experiment resists order effects, discomfort and incomparable sessions',()=>{let m=trial();for(let i=0;i<6;i++)m=paired(m,i,i%2?12:6,i%2?6:12);assert.equal(trialOutcome(m.trials[0]).status,'unclear');m=trial();for(let i=0;i<6;i++)m=paired(m,i,6,12,{comparable:i!==2});assert.equal(trialOutcome(m.trials[0]).status,'insufficient');m=trial();m=paired(m,0,6,12,{discomfort:true});assert.equal(m.trials[0].status,'cancelled');assert.equal(trialOutcome(m.trials[0]).status,'stopped-for-discomfort');assert.throws(()=>validateState({...m,trials:[{...m.trials[0],status:'active'}]}))});
test('negative personal experiment history is not silently treated as success',()=>{let m=trial();for(let i=0;i<6;i++)m=paired(m,i,12,6);m=finishTrial(m,'trial');assert.equal(approachHistory(m,'doubles','fixed','practice','attention cue','normal cue','external cue').policy,'do-not-repeat-without-new-evidence');assert.equal(approachHistory(m,'doubles','other','practice','attention cue','normal cue','external cue').notFavoured,0)});
test('session planner preserves minutes, prerequisites and beginner equivalence',()=>{let m=emptyMemory(),x=deep(m,day(0)),active=currentPlan(m,x,day(0));for(const skill of library.map(x=>x.skill))assert.deepEqual(drillOptions(skill,1),drillOptions(skill,2));assert.equal(trainingRecommendation(m,x,day(0),active,2).mode,'not-yet-available');const p=trainingRecommendation(m,x,day(0),active,1);assert.equal(p.segments.reduce((n,g)=>n+g.minutes,0),60);assert.equal(p.segments[0].minutes,10);assert.ok(p.segments.every(g=>g.minutes>=5));const s={id:'s',day:day(0),number:1,status:'completed',segments:p.segments.map(g=>({skill:g.skill,drill:g.drill,minutes:g.minutes}))};m=logSession(m,s);assert.equal(trainingRecommendation(m,x,day(0),active,1).mode,'already-recorded');assert.equal(trainingRecommendation(m,x,day(0),active,2).segments.reduce((n,g)=>n+g.minutes,0),60);assert.throws(()=>logSession(m,s));assert.equal(validateState(m).sessions.length,1);assert.equal(trainingRecommendation(m,{...x,decision:'stop'},day(0),active,2).segments.length,0)});
test('v0.1 backups migrate without replacing existing measurements or facts',()=>{let m=series();m=setFact(m,'preferred double','D20','confirmed');const v=validateState(m);assert.deepEqual(v.observations,m.observations);assert.deepEqual(v.facts,m.facts);assert.equal(v.answers.length+v.trials.length+v.changes.length+v.sessions.length,0)});
test('seeded diagnostic holdout: independent profiles with variable exposure, decline, fatigue and stable performance',()=>{let seed=0x908631;const rand=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);for(let player=0;player<1000;player++){const mode=player%5,skill=['doubles','singles','bull','checkout','switching'][Math.floor(player/5)%5];let m=emptyMemory();const base=25+Math.floor(rand()*8);for(let j=0;j<28;j++){const hits=base+Math.floor(rand()*3)-1-((mode!==0&&j>=21)?13:0);m.observations.push(obs(j,skill,hits));}if(mode===2||mode===3||mode===4)m=recordAnswer(m,{day:day(28),skill,context:'practice',protocol:'fixed',question:mode===2?'equipment':mode===3?'protocol':'comfort',answer:mode===3?'no':'yes'});const x=deep(m,day(28));assert.equal(x.decision,['balanced','temporary-focus','investigate','investigate','stop'][mode]);assert.equal(x.focus,mode===1?skill:null)}});

import {createGoal,goalProgress,closeGoal,preferredDoubles,combinedExposure} from '../site/engine/goals.mjs';
import {advice} from '../site/engine/tactics.mjs';
test('measurable goals use comparable days and require repeated success',()=>{let m=emptyMemory();const g={id:'goal',skill:'doubles',context:'practice',protocol:'fixed',start:day(7),review:day(35),target:.4};m=createGoal(m,g);for(let i=0;i<14;i++)m=addObservation(m,obs(i,'doubles',i<7?12:30));assert.equal(goalProgress(m,m.goals[0],day(13)).status,'target-observed');assert.equal(goalProgress(m,m.goals[0],day(13)).baseline,.2);assert.equal(goalProgress(m,m.goals[0],day(8)).status,'insufficient');assert.throws(()=>createGoal(m,{...g,id:'other'}));assert.equal(validateState(closeGoal(m,'goal')).goals[0].status,'closed');assert.throws(()=>createGoal(emptyMemory(),{...g,target:40}));assert.equal(goalProgress({...m,observations:m.observations.map(x=>x.day===day(13)?{...x,hits:12}:x)},m.goals[0],day(13)).status,'promising-not-consistent')});
test('actual session exposure contributes once when overlapping manual logs',()=>{let m=emptyMemory();m.exposure=[{day:day(0),skill:'doubles',minutes:8},{day:day(0),skill:'scoring',minutes:20}];m=logSession(m,{id:'s',day:day(0),number:1,status:'partial',segments:[{skill:'doubles',drill:'double-prep',minutes:10},{skill:'warmup',drill:'warmup',minutes:10}]});const rows=combinedExposure(m);assert.equal(rows.find(x=>x.skill==='doubles').minutes,10);assert.equal(rows.find(x=>x.skill==='doubles').overlap,true);assert.equal(rows.find(x=>x.skill==='scoring').minutes,20);assert.equal(rows.length,2)});
test('checkout advice is legal, personal preferences are not accuracy estimates, and misses recalculate',()=>{let m=setFact(emptyMemory(),'Preferred double','D16','confirmed');assert.equal(preferredDoubles(m)[0],'D16');assert.equal(preferredDoubles(setFact(m,'Preferred double','D99'))[0],'D20');const a=advice(m,{score:40,darts:3,actual:['S20'],opponent:170});assert.equal(a.remaining,20);assert.equal(a.dartsLeft,2);assert.ok(a.options.some(x=>x.path.join()==='D10'));assert.equal(a.opponentCanFinish,true);assert.equal(advice(m,{score:40,actual:['S20','S20']}).status,'bust');assert.equal(advice(m,{score:40,actual:['D20']}).status,'finished');assert.throws(()=>advice(m,{score:40,actual:['D20','S1']}));assert.equal(advice(m,{score:169}).status,'setup-required');assert.equal(advice(m,{score:101,doubleIn:true,opened:false,actual:['T20']}).status,'double-in-required');assert.equal(advice(m,{score:101,doubleIn:true,opened:false,actual:['T20','D20']}).remaining,61);for(const score of [2,40,81,99,110,170])for(const x of advice(m,{score}).options)assert.equal(visit(score,x.path).finished,true)});
test('focused plans cover every measured skill with unique segments',()=>{for(const skill of library.map(x=>x.skill)){const p=plan(skill);assert.ok(p.some(x=>x.skill===skill));assert.equal(p.reduce((n,x)=>n+x.minutes,0),60);assert.ok(p.every(x=>x.minutes>=5));const t=trainingRecommendation({ ...emptyMemory(),interventions:[{id:'i',skill}]},{decision:'temporary-focus'},day(0),{mode:'accepted-temporary-focus',intervention:'i'},1);assert.equal(new Set(t.segments.map(x=>x.skill)).size,t.segments.length);assert.equal(t.segments.reduce((n,x)=>n+x.minutes,0),60)}});

import {confirmCurrentDecline} from '../site/engine/diagnosis.mjs';
test('recent confirmation distinguishes persistent decline, recovery and transient noise',()=>{const m=emptyMemory();for(let i=0;i<42;i++)m.observations.push(obs(i,'doubles',i>=28?12:30));const issue={skill:'doubles',context:'practice',protocol:'fixed'};assert.equal(confirmCurrentDecline(m,issue,day(42)).status,'confirmed');const recovery={...m,observations:m.observations.map((o,i)=>({...o,hits:i>=14&&i<28?12:30}))};assert.equal(confirmCurrentDecline(recovery,issue,day(42)).status,'not-confirmed');assert.equal(deep(recovery,day(42)).focus,null);assert.equal(confirmCurrentDecline(m,issue,day(100)).status,'insufficient')});
test('10,000 noisy synthetic histories: safeguard unnecessary focus while retaining severe decline detection',()=>{let seed=0x88bb7761;const rng=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296),counts=Array.from({length:5},()=>({focus:0,investigate:0})),skills=['doubles','checkout','bull','singles','switching','trebles','grouping','pressure'];for(let i=0;i<10000;i++){const type=i%5,skill=skills[Math.floor(i/5)%skills.length],base=.25+rng()*.45;let m=emptyMemory();let block=0;for(let j=0;j<42;j++){if(j%3===0)block=(rng()-.5)*.12;if(type===3&&j%9!==0)continue;const delta=type===1||type===2?j>=28?-.2:0:type===4&&j>=14&&j<28?-.2:0,p=Math.min(.97,Math.max(.03,base+block+delta)),attempts=30+Math.floor(rng()*31);let hits=0;for(let k=0;k<attempts;k++)hits+=rng()<p?1:0;m.observations.push(obs(j,skill,hits,'practice','fixed',attempts))}if(type===2)m=recordAnswer(m,{day:day(42),skill,context:'practice',protocol:'fixed',question:'equipment',answer:'yes'});const x=deep(m,day(42));counts[type].focus+=Number(x.decision==='temporary-focus');counts[type].investigate+=Number(x.decision==='investigate')}assert.ok(counts[0].focus<=40,'Stable focus below 2% for this simulation');assert.ok(counts[1].focus>=1600,'Strong decline focus at least 80% for this simulation');assert.ok(counts[1].focus+counts[1].investigate>=1900);assert.equal(counts[2].focus,0);assert.equal(counts[3].focus,0);assert.equal(counts[4].focus,0)});

import {recordClinic,clinicReview,DOMAINS} from '../site/engine/clinic.mjs';
import {recordSetup,setupComparison} from '../site/engine/equipment-profile.mjs';
import {recordFollowup,followupReview} from '../site/engine/followup.mjs';
import {fullReport,canAccept,verifiedPlan} from '../site/engine/executive.mjs';
import {questionAgenda,learningLedger} from '../site/engine/strategy.mjs';
const scope={skill:'doubles',context:'practice',protocol:'Fixed D1–D20'};
const clinicRow=(id,day,extra={})=>({id,day,...scope,domain:'release',observation:'repeated difference',condition:'normal practice',method:'video review',pain:false,note:'Observed difference only',...extra});
test('unified executive preserves nine scenarios and dynamic answer revision',()=>{const expected={decline:'temporary-focus',stable:'balanced',fatigue:'investigate',equipment:'investigate',measurement:'investigate',sparse:'balanced',pressure:'investigate',pain:'stop',exposure:'temporary-focus'};for(const [id] of SCENARIOS){const s=scenario(id),x=fullReport(s.memory,s.day);assert.equal(x.decision,expected[id]);assert.equal(x.trace.decision,x.decision);assert.equal(x.active.plan.length===0,id==='pain');}const s=scenario('decline');assert.equal(fullReport(recordAnswer(s.memory,{...scope,day:s.day,question:'equipment',answer:'yes'}),s.day).decision,'investigate')});
test('technical observation requires corroboration before a focus veto and never diagnoses a fault',()=>{const s=scenario('decline');let m=recordClinic(s.memory,clinicRow('a','2026-01-12'));assert.equal(clinicReview(m,scope,s.day).hypotheses.find(h=>h.domain==='release').status,'reported-observation');assert.equal(fullReport(m,s.day).decision,'temporary-focus');m=recordClinic(m,clinicRow('b','2026-01-13'));assert.equal(clinicReview(m,scope,s.day).hypotheses.find(h=>h.domain==='release').status,'corroborated-observation');assert.equal(fullReport(m,s.day).decision,'investigate');assert.equal(clinicReview(m,scope,s.day).hypotheses.length,DOMAINS.length);assert.equal(validateState(m).clinic.length,2);assert.equal(clinicReview(m,{...scope,protocol:'other'},s.day).priority,null)});
test('technical or experiment discomfort stops all normal training even without a decline',()=>{let m=recordClinic(emptyMemory(),clinicRow('p',day(0),{pain:true}));assert.equal(fullReport(m,day(1)).decision,'stop');assert.equal(fullReport(m,day(1)).active.plan.length,0);assert.equal(fullReport(m,day(10)).decision,'balanced');m=trial();m=paired(m,0,6,12,{discomfort:true});assert.equal(fullReport(m,day(1)).decision,'stop')});
test('question agenda prioritises safety and does not immediately repeat unknown answers',()=>{const s=scenario('decline');let m=s.memory;assert.equal(fullReport(m,s.day).strategy.agenda.next.id,'comfort');m=recordAnswer(m,{...scope,day:s.day,question:'comfort',answer:'unknown'});assert.equal(fullReport(m,s.day).strategy.agenda.next.id,'protocol');m=recordAnswer(m,{...scope,day:s.day,question:'protocol',answer:'no'});assert.equal(fullReport(m,s.day).decision,'investigate');assert.equal(fullReport(m,s.day).strategy.agenda.questions.some(q=>q.id==='protocol'),false)});
test('equipment snapshot compares known changes, never treats missing values as differences',()=>{const a={id:'a',day:day(0),name:'baseline',comfort:'comfortable',values:{weight:'24g','stem length':'short'}},b={...a,id:'b',name:'alternative',values:{weight:'24g','stem length':'medium'}};const x=setupComparison(a,b);assert.deepEqual(x.changed,['stem length']);assert.deepEqual(x.unchanged,['weight']);assert.equal(x.decision,'compare-single-variable');assert.equal(setupComparison(a,{...b,values:{weight:'25g','stem length':'medium'}}).decision,'isolate-variables');assert.equal(setupComparison(a,{...b,comfort:'uncomfortable'}).decision,'stop-and-review');assert.equal(setupComparison(a,{...b,values:{}}).decision,'no-established-change');assert.equal(validateState(recordSetup(recordSetup(emptyMemory(),a),b)).setups.length,2)});
test('new evidence can invalidate an unaccepted proposal and interrupt an accepted intervention',()=>{const s=scenario('decline');let m=propose(s.memory,fullReport(s.memory,s.day),'i',s.day);assert.equal(canAccept(m,m.interventions[0],s.day).allowed,true);assert.equal(canAccept(m,m.interventions[0],'2026-01-25').allowed,false);let changed=recordAnswer(m,{...scope,day:s.day,question:'equipment',answer:'yes'});assert.equal(canAccept(changed,changed.interventions[0],s.day).allowed,false);m=respond(m,'i','accepted',s.day);m=recordChange(m,{id:'new',day:'2026-01-16',field:'equipment',description:'changed weight'});assert.equal(fullReport(m,'2026-01-16').active.mode,'review-new-evidence')});
test('delayed learning requires dates and distinct transfer context; records are validated',()=>{let m=trial();for(let i=0;i<6;i++)m=paired(m,i,6,12);m=finishTrial(m,'trial');const t=m.trials[0],row={trialId:t.id,skill:t.skill,protocol:t.protocol,context:t.context,kind:'retention',phase:'followup',attempts:20,hits:12,comparable:true,confounder:false};assert.throws(()=>recordFollowup(m,{...row,id:'early',day:day(6)}));for(let i=12;i<19;i++)m=recordFollowup(m,{...row,id:'r'+i,day:day(i)});assert.equal(followupReview(m,t,day(18))[0].status,'observed-benefit');assert.equal(followupReview(m,t,day(14))[0].status,'insufficient');assert.equal(validateState(m).followups.length,7);assert.throws(()=>recordFollowup(m,{...row,id:'bad',day:day(20),kind:'transfer'}));assert.equal(followupReview({...m,followups:m.followups.map((o,i)=>({...o,confounder:i===0}))},t,day(18))[0].status,'confounded')});
test('multi-skill decisions are ordered deterministically and focus is singular',()=>{const s=scenario('decline');let m=s.memory;for(let i=0;i<14;i++)m=addObservation(m,{id:'co'+i,day:'2026-01-'+String(i+1).padStart(2,'0'),skill:'checkout',context:'practice',protocol:'fixed checkout',attempts:60,hits:i<7?30:12});const x=fullReport(m,s.day),reversed=fullReport({...m,observations:[...m.observations].reverse()},s.day);assert.equal(x.focus,reversed.focus);assert.equal(x.strategy.clusters.length,1);assert.equal(x.strategy.clusters[0].skills.length,2);assert.equal(x.plan.reduce((n,g)=>n+g.minutes,0),60);assert.equal(x.development.skills.length,11);assert.equal(x.development.missingBenchmarks.includes('bull'),true)});
test('all new evidence links point to structured knowledge and backups keep original data',()=>{const s=scenario('equipment'),x=fullReport(s.memory,s.day);const ids=new Set(knowledge.map(k=>k.id));for(const i of x.issues)for(const a of i.actions)for(const k of a.sources)assert.ok(ids.has(k.id));const v=validateState(s.memory);assert.deepEqual(v.observations,s.memory.observations);assert.equal(v.clinic.length+v.setups.length+v.followups.length,0)});

import {targetComparison,scoringComparison,directionReview} from '../site/engine/target-analysis.mjs';
import {analyseLeg,recordLeg,legEvidence,legSummary,parseVisits} from '../site/engine/match.mjs';
test('matched target comparison uses paired days rather than pooling different sessions',()=>{let m=emptyMemory();for(let i=0;i<10;i++)for(let j=0;j<10;j++){m=appendThrow(m,{id:'a'+i+'-'+j,day:day(i),context:'practice',protocol:'paired',aim:'D20',actual:j<8?'D20':'S20'});m=appendThrow(m,{id:'b'+i+'-'+j,day:day(i),context:'practice',protocol:'paired',aim:'D16',actual:j<3?'D16':'S16'})}const q={first:'D20',second:'D16',context:'practice',protocol:'paired',day:day(9)},x=targetComparison(m,q);assert.equal(x.status,'first-higher');assert.equal(x.pairedDays,10);assert.equal(x.attemptsA,100);assert.equal(targetComparison(m,{...q,context:'competition'}).status,'insufficient');assert.equal(targetComparison({...m,throws:m.throws.map(o=>o.aim==='D16'?{...o,day:day(20)}:o)},{...q,day:day(21)}).status,'insufficient')});
test('scoring target comparison measures actual points and directional review needs repeated neighbour misses',()=>{const m=emptyMemory();m.throws=[];for(let i=0;i<10;i++)for(let j=0;j<10;j++){for(const aim of ['T20','T19','T18'])m.throws.push({id:aim+i+'-'+j,day:day(i),context:'practice',protocol:'score',aim,actual:aim==='T19'?'T19':aim==='T20'?'S1':'S18'});m.throws.push({id:'dir'+i+'-'+j,day:day(i),context:'practice',protocol:'dir',aim:'D20',actual:j<8?'S1':'S5'})}const x=scoringComparison(m,{context:'practice',protocol:'score',day:day(9)});assert.equal(x.recommendation,'T19');assert.equal(x.estimates[0].average,171);assert.equal(directionReview(m,{context:'practice',protocol:'dir',day:day(9),aim:'D20'}).status,'clockwise-pattern');assert.equal(directionReview(m,{context:'practice',protocol:'dir',day:day(9),aim:'D16'}).status,'insufficient')});
test('verified legs distinguish actual aims, credited points, checkout visits and first nine',()=>{const raw={id:'l',day:day(0),start:501,doubleIn:false,context:'competition',result:'won',visits:parseVisits('T20 T20 T20\nT20 T20 T20\nT20 T19 D12')};const l=analyseLeg(raw);assert.equal(l.remaining,0);assert.equal(l.average,167);assert.equal(l.firstNineDarts,9);assert.equal(l.firstNine,167);assert.equal(l.checkoutVisits,1);assert.equal(l.checkoutWins,1);assert.equal(l.unknownIntent,9);const m=recordLeg(emptyMemory(),raw);assert.equal(legEvidence(m,day(1)).some(o=>o.skill==='doubles'),false);assert.equal(legSummary(m,day(1))[0].checkoutVisitRate,1);assert.equal(validateState(m).legs.length,1);assert.throws(()=>analyseLeg({...raw,result:'lost'}));assert.throws(()=>recordLeg(m,raw));assert.equal(fullReport(m,day(1)).match[0].average,167)});
test('leg replay handles bust, double-in and actual finishing intent without inference',()=>{const raw={id:'l2',day:day(0),start:101,doubleIn:false,context:'practice',result:'won',visits:parseVisits('T20>T20 S1>S1 D20>S20\nD10>D10')};const l=analyseLeg(raw);assert.equal(l.finishAttempts,2);assert.equal(l.finishHits,1);assert.equal(l.thrown,4);assert.equal(l.remaining,0);assert.throws(()=>analyseLeg({...raw,visits:parseVisits('T20 S1 S20\nS10 S10 S20')}));const di={...raw,doubleIn:true,visits:parseVisits('T20 D20 T20\nS1 D30')};assert.throws(()=>analyseLeg(di));const diWin={...raw,doubleIn:true,visits:parseVisits('T20 D20 T19\nD2')};assert.equal(analyseLeg(diWin).remaining,0);assert.equal(analyseLeg(diWin).thrown,4);const lost={...raw,result:'lost',visits:parseVisits('T20 S1 S20\nS10 S10')};const x=analyseLeg(lost);assert.equal(x.busts,1);assert.equal(x.remaining,20);assert.equal(x.points,81);assert.equal(x.thrown,5);assert.equal(x.unknownIntent,5)});

test('seeded multi-skill longitudinal executive stress: safety, isolation and bounded practice',()=>{let seed=0x3077b5;const rng=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);const skills=['doubles','checkout','scoring'];for(let player=0;player<300;player++){let m=emptyMemory();const mode=player%6,affected=skills[player%3];for(let week=0;week<104;week++){for(const skill of skills){const d=week*7,decline=week>=100&&skill===affected&&mode!==0;const hits=skill==='scoring'?1000+Math.floor(rng()*80)-(decline?300:0):30+Math.floor(rng()*5)-(decline?15:0);m.observations.push(obs(d,skill,hits,'practice','fixed'));}}const when=day(103*7);if(mode===2)m=recordClinic(m,clinicRow('pain'+player,when,{skill:affected,protocol:'fixed',pain:true}));if(mode===3)m=recordAnswer(m,{skill:affected,context:'practice',protocol:'fixed',day:when,question:'protocol',answer:'no'});if(mode===4)m=recordAnswer(m,{skill:affected,context:'practice',protocol:'fixed',day:when,question:'equipment',answer:'yes'});const before=JSON.stringify(m),report=fullReport(m,when);assert.equal(JSON.stringify(m),before);assert.equal(report.trace.decision,report.decision);assert.equal(report.active.plan.reduce((n,g)=>n+g.minutes,0),mode===2?0:60);if(mode===2)assert.equal(report.decision,'stop');if(mode===3||mode===4)assert.ok(report.focus!==affected);if(report.focus){assert.ok(report.issues.some(i=>i.skill===report.focus&&i.protocol===report.focusProtocol&&i.context===report.focusContext&&i.confirmation.status==='confirmed'&&i.action==='temporary-focus'));assert.equal(report.active.mode,'balanced-until-accepted')}assert.equal(report.development.skills.length,11);assert.equal(fullReport(m,day(103*7-90)).safety.stop,false);}});
test('future and stale observations cannot change a historical executive decision',()=>{const s=scenario('decline'),m=s.memory;const x=fullReport(m,s.day);const n={...m,observations:[...m.observations,{id:'future',day:'2027-01-01',skill:'doubles',context:'practice',protocol:'Fixed D1–D20',attempts:100,hits:99}]};assert.equal(fullReport(n,s.day).decision,x.decision);assert.equal(fullReport(n,s.day).focus,x.focus);assert.equal(fullReport(m,'2026-06-01').decision,'balanced')});

test('three new executive scenarios demonstrate grouped issues, technical veto and ranked questions',()=>{const a=scenario('multi'),r=fullReport(a.memory,a.day);assert.equal(r.strategy.clusters.length,1);assert.equal(r.issues.length,2);assert.equal(r.focus,'checkout');const b=scenario('technical'),t=fullReport(b.memory,b.day);assert.equal(t.decision,'investigate');assert.equal(t.issues[0].clinic.priority,'release');const c=scenario('unknown');assert.equal(fullReport(c.memory,c.day).strategy.agenda.next.id,'protocol')});

import {checkDecision,enforceDecision} from '../site/engine/verification.mjs';
test('independent verifier refuses unsafe plans, unsupported focus and unconsented interventions',()=>{const s=scenario('decline'),x=fullReport(s.memory,s.day);assert.equal(x.verification.status,'passed');const bad={...x,issues:x.issues.map(i=>({...i,confirmation:{status:'not-confirmed'}}))};assert.equal(checkDecision(s.memory,bad).status,'failed');assert.equal(enforceDecision(s.memory,bad).decision,'investigate');assert.equal(enforceDecision(s.memory,bad).focus,null);const unsafe={...x,safety:{stop:true,flags:[]}};assert.equal(enforceDecision(s.memory,unsafe).decision,'stop');assert.equal(enforceDecision(s.memory,unsafe).active.plan.length,0);const unconsented={...x,active:{...x.active,mode:'accepted-temporary-focus',intervention:'nonexistent'}};assert.ok(checkDecision(s.memory,unconsented).faults.includes('missing-consent'))});

test('personal learning distinguishes initial favourable results from delayed evidence',()=>{let m=trial();for(let i=0;i<6;i++)m=paired(m,i,6,12);m=finishTrial(m,'trial');const t=m.trials[0];assert.equal(learningLedger(m,t,day(6)).promising.length,1);assert.equal(learningLedger(m,t,day(6)).retained.length,0);for(let i=12;i<19;i++)m=recordFollowup(m,{id:'r'+i,trialId:t.id,skill:t.skill,context:t.context,protocol:t.protocol,kind:'retention',phase:'followup',day:day(i),attempts:20,hits:6,comparable:true,confounder:false});const ledger=learningLedger(m,t,day(18));assert.equal(ledger.blocked.length,1);assert.equal(ledger.retained.length,0);const better={...m,followups:m.followups.map(o=>({...o,hits:12}))};assert.equal(learningLedger(better,t,day(18)).retained.length,1)});

import {newPlayer,query as coachQuery,command as coachCommand,batch as coachBatch} from '../site/engine/coach-api.mjs';
import {ask,interpret} from '../site/engine/coach-dialogue.mjs';
import {nextActions} from '../site/engine/next-actions.mjs';
import {importBenchmarks,integrationExample} from '../site/engine/host-adapter.mjs';
const envelope=(type,day,payload={})=>({version:1,type,day,payload});
test('local integration contract is read-only for queries and explicitly confirmed for commands',()=>{const s=scenario('decline'),m=s.memory,before=JSON.stringify(m),q=envelope('review',s.day);const x=coachQuery(m,q);assert.equal(x.result.decision,'temporary-focus');assert.equal(x.result.verification.status,'passed');assert.equal(JSON.stringify(m),before);const req=envelope('fact',s.day,{key:'preferred double',value:'D16',evidence:'confirmed'});assert.throws(()=>coachCommand(m,req));assert.equal(coachCommand(m,req,{confirmed:true}).state.facts.at(-1).value,'D16');assert.equal(JSON.stringify(m),before);assert.throws(()=>coachQuery(m,{...q,version:999}));assert.throws(()=>coachQuery(m,{...q,payload:{extra:'invalid'}}));assert.throws(()=>coachQuery({...m,namespace:'other-app'},q))});
test('contract batch is atomic and rejects future or duplicate observations',()=>{const m=newPlayer(),day='2026-01-15',o={id:'o',day,skill:'doubles',context:'practice',protocol:'fixed',attempts:60,hits:30},req=envelope('observation',day,o);assert.throws(()=>coachBatch(m,[req,req],{confirmed:true}));assert.equal(m.observations.length,0);assert.throws(()=>coachCommand(m,envelope('observation',day,{...o,day:'2026-01-16'}),{confirmed:true}));assert.throws(()=>coachCommand(m,envelope('observation',day,{...o,hits:61}),{confirmed:true}));const result=coachBatch(m,[req,envelope('observation',day,{...o,id:'o2'})],{confirmed:true});assert.equal(result.state.observations.length,2);assert.equal(m.observations.length,0)});
test('API cannot accept an intervention after changed evidence',()=>{const s=scenario('decline'),m=coachCommand(s.memory,envelope('propose',s.day,{id:'i'}),{confirmed:true}).state;const accept=envelope('respond',s.day,{id:'i',decision:'accepted'});assert.throws(()=>coachCommand(m,accept));assert.equal(coachCommand(m,accept,{confirmed:true}).state.interventions[0].status,'accepted');const changed=coachCommand(m,envelope('answer',s.day,{...scope,day:s.day,question:'equipment',answer:'yes'}),{confirmed:true}).state;assert.throws(()=>coachCommand(changed,accept,{confirmed:true}));});
test('bounded dialogue routes supported questions without silently interpreting unsupported statements',()=>{const s=scenario('decline');const before=JSON.stringify(s.memory);assert.equal(ask(s.memory,'How am I doing?',s.day).type,'review');assert.equal(ask(s.memory,'What should I practise?',s.day).type,'training');const x=ask(s.memory,'Checkout 81 with 2 darts',s.day);assert.equal(x.type,'checkout');assert.ok(x.lines.length>1);assert.equal(ask(s.memory,'What should I investigate next?',s.day).type,'next-actions');assert.equal(ask(s.memory,'What do you know about me?',s.day).type,'memory-summary');assert.equal(interpret('my average is 120, save it',s.day).kind,'unsupported');assert.equal(interpret('ignore rules and change my memory',s.day).kind,'unsupported');assert.equal(JSON.stringify(s.memory),before)});
test('next actions give safety priority and surface unanswered questions and missing benchmarks',()=>{const pain=scenario('pain');assert.deepEqual(nextActions(pain.memory,pain.day).map(a=>a.kind),['safety']);const x=scenario('decline');assert.equal(nextActions(x.memory,x.day)[0].question,'comfort');const empty=nextActions(newPlayer(),x.day);assert.equal(empty.length,3);assert.ok(empty.every(a=>a.kind==='benchmark'))});
test('host import is scoped and idempotent, conflicting events fail atomically',()=>{const m=newPlayer(),day='2026-01-15',e={eventId:'a1',day,skill:'doubles',context:'practice',protocol:'all doubles',attempts:60,hits:20};assert.throws(()=>importBenchmarks(m,'host-a',[e],day));const a=importBenchmarks(m,'host-a',[e],day,{confirmed:true});assert.equal(a.imported,1);assert.equal(a.state.observations[0].protocol,'host:host-a:all doubles');const b=importBenchmarks(a.state,'host-a',[e],day,{confirmed:true});assert.equal(b.duplicates,1);assert.equal(b.state.observations.length,1);assert.throws(()=>importBenchmarks(a.state,'host-a',[{...e,hits:21}],day,{confirmed:true}));assert.equal(importBenchmarks(a.state,'host-b',[e],day,{confirmed:true}).state.observations.length,2);assert.equal(m.observations.length,0);assert.throws(()=>importBenchmarks(m,'host-a',[{...e,context:'unknown'}],day,{confirmed:true}));assert.throws(()=>importBenchmarks(m,'host-a',[{...e,protocol:''}],day,{confirmed:true}));assert.throws(()=>importBenchmarks(m,'bad/source',[e],day,{confirmed:true}))});
test('isolated integration demonstration connects host evidence to verified coaching and training',()=>{const x=integrationExample('2026-01-15');assert.equal(x.imported,14);assert.equal(x.retried,14);assert.equal(x.total,14);assert.equal(x.focus,'doubles');assert.equal(x.decision,'temporary-focus');assert.equal(x.trainingMinutes,60);assert.equal(x.verification,'passed')});

import {parseHostExport,previewHostExport} from '../site/engine/host-adapter.mjs';
test('portable host export preview never mutates state and validates its envelope',()=>{const m=newPlayer(),day='2026-01-15',raw=JSON.stringify({format:'DCI-benchmark-events',version:1,source:'training-app',events:[{eventId:'12345678-1234-1234-1234-123456789012',day,skill:'doubles',context:'practice',protocol:'D1-D20 fixed',attempts:60,hits:20}]});const preview=previewHostExport(m,raw,day);assert.equal(preview.imported,1);assert.equal(m.observations.length,0);assert.equal(preview.scopes.length,1);assert.equal(parseHostExport(raw).source,'training-app');assert.throws(()=>parseHostExport('[]'));assert.throws(()=>parseHostExport(raw.replace('"version":1','"version":2')));assert.throws(()=>parseHostExport(raw.replace('"hits":20','"hits":70')));assert.throws(()=>parseHostExport(raw.replace('"source":"training-app"','"source":"training-app","unsafe":true')));});
